3. Implement the CSV downloader service:

```typescript
// app/services/csv-downloader.ts
import { inject as service } from '@ember/service';
import { A } from '@ember/array';
import { task, timeout } from 'ember-concurrency';
import { computed } from '@ember/object';
import { read } from 'ember-cli-htmlbars';
import { worker } from 'ember-cli-web-worker';

export default class CsvDownloaderService {
  @service('store') store;

  @task
  async downloadCSV(data) {
    const headers = data[0];
    const rows = data.slice(1);

    const worker = worker(async () => {
      const blob = new Blob([this.csvString(headers, rows)], {
        type: 'text/csv;charset=utf-8;',
      });

      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'export.csv';
      a.click();
      URL.revokeObjectURL(url);
    });

    await worker.perform(data);
  }

  csvString(headers, rows) {
    const headerRow = headers.map((header) => `"${header}"`).join(',');
    const rowStrings = rows.map((row) => {
      return row.map((cell) => `"${cell}"`).join(',');
    });

    return [headerRow, ...rowStrings].join('\n');
  }

  @computed('store.content')
  get data() {
    const content = this.store.content;
    return content ? A(content) : A([]);
  }
}
